using namespace std;

namespace io {

    const size_t BUFFER_SIZE = 8192;

    class Input {
        deque<string> token_buffer;
        string remaining;

        void fill_buffer() {
            while (token_buffer.empty()) {
                static char minibuffer[BUFFER_SIZE];
                cin.read(minibuffer, BUFFER_SIZE);
                streamsize size = cin.gcount();

                remaining += string(minibuffer, minibuffer + size);

                auto trim = [](const string &s) {
                    size_t start = 0;
                    while (start < s.size() && isspace(static_cast<unsigned char>(s[start]))) ++start;
                    size_t end = s.size();
                    while (end > start && isspace(static_cast<unsigned char>(s[end - 1]))) --end;
                    return s.substr(start, end - start);
                };

                string trimmed = trim(remaining);

                if (!trimmed.empty()) {
                    stringstream ss(trimmed);
                    string token;
                    while (ss >> token) {
                        token_buffer.push_back(token);
                    }

                    if (size > 0 && !isspace(static_cast<unsigned char>(remaining.back()))) {
                        remaining = token_buffer.back();
                        token_buffer.pop_back();
                    } else {
                        remaining.clear();
                    }

                } else if (size == 0) {
                    throw runtime_error("EOF");
                }
            }
        }

