        T next() {
            fill_buffer();
            string s = token_buffer.front();
            token_buffer.pop_front();
            stringstream ss(s);
            T val;
            ss >> val;
            return val;
        }

        vector<unsigned char> next_ascii_string() {
            fill_buffer();
            string s = token_buffer.front();
            token_buffer.pop_front();
            return vector<unsigned char>(s.begin(), s.end());
        }
    };
